def build(Q):
    D = lambda a: dict(zip(("en", "fr", "rw", "sw"), a))
    out = []
    for q, opts, ans, why, slip in ROWS:
        out.append(Q("cybersecurity", q, D(opts), ans, why, slip))
    return out
